macro_rules! deps {
    () => {
        CoinFlipper!();
        Rng!();
    };
}

macro_rules! IteratorRandom {
    () => {
        deps!();
        # [doc = " Extension trait on iterators, providing random sampling methods."] # [doc = ""] # [doc = " This trait is implemented on all iterators `I` where `I: Iterator + Sized`"] # [doc = " and provides methods for"] # [doc = " choosing one or more elements. You must `use` this trait:"] # [doc = ""] # [doc = " ```"] # [doc = " use rand::seq::IteratorRandom;"] # [doc = ""] # [doc = " let faces = \"😀😎😐😕😠😢\";"] # [doc = " println!(\"I am {}!\", faces.chars().choose(&mut rand::rng()).unwrap());"] # [doc = " ```"] # [doc = " Example output (non-deterministic):"] # [doc = " ```none"] # [doc = " I am 😀!"] # [doc = " ```"] pub trait IteratorRandom : Iterator + Sized { # [doc = " Uniformly sample one element"] # [doc = ""] # [doc = " Assuming that the [`Iterator::size_hint`] is correct, this method"] # [doc = " returns one uniformly-sampled random element of the slice, or `None`"] # [doc = " only if the slice is empty. Incorrect bounds on the `size_hint` may"] # [doc = " cause this method to incorrectly return `None` if fewer elements than"] # [doc = " the advertised `lower` bound are present and may prevent sampling of"] # [doc = " elements beyond an advertised `upper` bound (i.e. incorrect `size_hint`"] # [doc = " is memory-safe, but may result in unexpected `None` result and"] # [doc = " non-uniform distribution)."] # [doc = ""] # [doc = " With an accurate [`Iterator::size_hint`] and where [`Iterator::nth`] is"] # [doc = " a constant-time operation, this method can offer `O(1)` performance."] # [doc = " Where no size hint is"] # [doc = " available, complexity is `O(n)` where `n` is the iterator length."] # [doc = " Partial hints (where `lower > 0`) also improve performance."] # [doc = ""] # [doc = " Note further that [`Iterator::size_hint`] may affect the number of RNG"] # [doc = " samples used as well as the result (while remaining uniform sampling)."] # [doc = " Consider instead using [`IteratorRandom::choose_stable`] to avoid"] # [doc = " [`Iterator`] combinators which only change size hints from affecting the"] # [doc = " results."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use rand::seq::IteratorRandom;"] # [doc = ""] # [doc = " let words = \"Mary had a little lamb\".split(' ');"] # [doc = " println!(\"{}\", words.choose(&mut rand::rng()).unwrap());"] # [doc = " ```"] fn choose < R > (mut self , rng : & mut R) -> Option < Self :: Item > where R : Rng + ? Sized , { let (mut lower , mut upper) = self . size_hint () ; let mut result = None ; if upper == Some (lower) { return match lower { 0 => None , 1 => self . next () , _ => self . nth (rng . random_range (.. lower)) , } ; } let mut coin_flipper = CoinFlipper :: new (rng) ; let mut consumed = 0 ; loop { if lower > 1 { let ix = coin_flipper . rng . random_range (.. lower + consumed) ; let skip = if ix < lower { result = self . nth (ix) ; lower - (ix + 1) } else { lower } ; if upper == Some (lower) { return result ; } consumed += lower ; if skip > 0 { self . nth (skip - 1) ; } } else { let elem = self . next () ; if elem . is_none () { return result ; } consumed += 1 ; if coin_flipper . random_ratio_one_over (consumed) { result = elem ; } } let hint = self . size_hint () ; lower = hint . 0 ; upper = hint . 1 ; } } # [doc = " Uniformly sample one element (stable)"] # [doc = ""] # [doc = " This method is very similar to [`choose`] except that the result"] # [doc = " only depends on the length of the iterator and the values produced by"] # [doc = " `rng`. Notably for any iterator of a given length this will make the"] # [doc = " same requests to `rng` and if the same sequence of values are produced"] # [doc = " the same index will be selected from `self`. This may be useful if you"] # [doc = " need consistent results no matter what type of iterator you are working"] # [doc = " with. If you do not need this stability prefer [`choose`]."] # [doc = ""] # [doc = " Note that this method still uses [`Iterator::size_hint`] to skip"] # [doc = " constructing elements where possible, however the selection and `rng`"] # [doc = " calls are the same in the face of this optimization. If you want to"] # [doc = " force every element to be created regardless call `.inspect(|e| ())`."] # [doc = ""] # [doc = " [`choose`]: IteratorRandom::choose"] # [allow (unknown_lints)] # [allow (clippy :: double_ended_iterator_last)] fn choose_stable < R > (mut self , rng : & mut R) -> Option < Self :: Item > where R : Rng + ? Sized , { let mut consumed = 0 ; let mut result = None ; let mut coin_flipper = CoinFlipper :: new (rng) ; loop { let mut next = 0 ; let (lower , _) = self . size_hint () ; if lower >= 2 { let highest_selected = (0 .. lower) . filter (| ix | coin_flipper . random_ratio_one_over (consumed + ix + 1)) . last () ; consumed += lower ; next = lower ; if let Some (ix) = highest_selected { result = self . nth (ix) ; next -= ix + 1 ; debug_assert ! (result . is_some () , "iterator shorter than size_hint().0") ; } } let elem = self . nth (next) ; if elem . is_none () { return result ; } if coin_flipper . random_ratio_one_over (consumed + 1) { result = elem ; } consumed += 1 ; } } # [doc = " Uniformly sample `amount` distinct elements into a buffer"] # [doc = ""] # [doc = " Collects values at random from the iterator into a supplied buffer"] # [doc = " until that buffer is filled."] # [doc = ""] # [doc = " Although the elements are selected randomly, the order of elements in"] # [doc = " the buffer is neither stable nor fully random. If random ordering is"] # [doc = " desired, shuffle the result."] # [doc = ""] # [doc = " Returns the number of elements added to the buffer. This equals the length"] # [doc = " of the buffer unless the iterator contains insufficient elements, in which"] # [doc = " case this equals the number of elements available."] # [doc = ""] # [doc = " Complexity is `O(n)` where `n` is the length of the iterator."] # [doc = " For slices, prefer [`IndexedRandom::sample`]."] fn sample_fill < R > (mut self , rng : & mut R , buf : & mut [Self :: Item]) -> usize where R : Rng + ? Sized , { let amount = buf . len () ; let mut len = 0 ; while len < amount { if let Some (elem) = self . next () { buf [len] = elem ; len += 1 ; } else { return len ; } } for (i , elem) in self . enumerate () { let k = rng . random_range (.. i + 1 + amount) ; if let Some (slot) = buf . get_mut (k) { * slot = elem ; } } len } # [doc = " Uniformly sample `amount` distinct elements into a [`Vec`]"] # [doc = ""] # [doc = " This is equivalent to `sample_fill` except for the result type."] # [doc = ""] # [doc = " Although the elements are selected randomly, the order of elements in"] # [doc = " the buffer is neither stable nor fully random. If random ordering is"] # [doc = " desired, shuffle the result."] # [doc = ""] # [doc = " The length of the returned vector equals `amount` unless the iterator"] # [doc = " contains insufficient elements, in which case it equals the number of"] # [doc = " elements available."] # [doc = ""] # [doc = " Complexity is `O(n)` where `n` is the length of the iterator."] # [doc = " For slices, prefer [`IndexedRandom::sample`]."] # [cfg (feature = "alloc")] fn sample < R > (mut self , rng : & mut R , amount : usize) -> Vec < Self :: Item > where R : Rng + ? Sized , { let mut reservoir = Vec :: with_capacity (amount) ; reservoir . extend (self . by_ref () . take (amount)) ; if reservoir . len () == amount { for (i , elem) in self . enumerate () { let k = rng . random_range (.. i + 1 + amount) ; if let Some (slot) = reservoir . get_mut (k) { * slot = elem ; } } } else { reservoir . shrink_to_fit () ; } reservoir } # [doc = " Deprecated: use [`Self::sample_fill`] instead"] # [deprecated (since = "0.9.2" , note = "Renamed to `sample_fill`")] fn choose_multiple_fill < R > (self , rng : & mut R , buf : & mut [Self :: Item]) -> usize where R : Rng + ? Sized , { self . sample_fill (rng , buf) } # [doc = " Deprecated: use [`Self::sample`] instead"] # [cfg (feature = "alloc")] # [deprecated (since = "0.9.2" , note = "Renamed to `sample`")] fn choose_multiple < R > (self , rng : & mut R , amount : usize) -> Vec < Self :: Item > where R : Rng + ? Sized , { self . sample (rng , amount) } }
    };
}

IteratorRandom!()